insert into public.profiles (id, name, age, sun, moon, rising, photo, aligns_back, founder, card, starter_day, starter_traded, blurb, deal_order, comet) values
  ('m24', 'Maya', 24, 'virgo', 'scorpio', 'cancer', 'img/people/p3.jpg', false, null, '{"initial":"Maya","serial":"№ 027","pull":"Slow burn","reading":[{"kind":"pull","text":"Mars in your Moon, she notices everything.","strength":3},{"kind":"push","text":"Her lists meet your naps. Somebody bends.","strength":2},{"kind":"align","text":"Earth to earth — steady ground, slow bloom.","strength":2}],"dealbreakers":"Late replies. Loud chewing. Anyone who hates dogs."}'::jsonb, null, false, 'ER nurse on nights. Alphabetised spice rack. Soft for dogs.', 0, false),
  ('r29', 'Rio', 29, 'leo', 'aries', 'sagittarius', 'img/people/p9.jpg', false, 18, '{"initial":"Rio","serial":"№ 029","pull":"Wild card","reading":[{"kind":"pull","text":"Sun on your Moon — instant warmth, big laughs.","strength":3},{"kind":"push","text":"Two fixed signs. Nobody backs down first.","strength":3},{"kind":"align","text":"Fire lights earth; you keep the flame from spreading.","strength":1}],"dealbreakers":"Flaking on plans. Small talk forever. No sense of adventure."}'::jsonb, null, false, 'Chef at a supper club. I’ll feed you before I flirt.', 1, false),
  ('j27', 'Juniper', 27, 'libra', 'gemini', 'aquarius', 'img/juniper.jpg', true, null, '{"initial":"Juniper","serial":"№ 031","pull":"Rare pull","house":"7th house","reading":[{"kind":"pull","text":"Mercury on your Moon, she gets it first try.","strength":3},{"kind":"push","text":"Her scales stall your schedule, decisions take two.","strength":2},{"kind":"align","text":"Earth holds air — she moves, you make it last. Venus rules you both.","strength":3}],"dealbreakers":"One-word texts. Refusing to talk it out the same night. Hating my group chats.","bio":"Gallery girl by day, playlist archivist by night. I read last pages first, cry at planetarium shows, and will absolutely rearrange your bookshelf by colour. Looking for someone who argues gently and means it.","religion":"Spiritual, not religious","lookingFor":"Long-term, open to slow","height":"5′6″","work":"Assistant curator","interests":["Film photography","Vinyl","Planetariums","Ceramics","Wine bars"]}'::jsonb, null, false, 'Assistant curator. Playlist archivist. Cries at planetariums.', 2, false),
  ('a31', 'Ari', 31, 'aquarius', 'libra', 'gemini', 'img/people/p6.jpg', false, null, '{"initial":"Ari","serial":"№ 033","pull":"Steady pull","reading":[{"kind":"pull","text":"Uranus wakes your Venus — nothing about this is routine.","strength":2},{"kind":"push","text":"You want a plan; they want a surprise.","strength":2},{"kind":"align","text":"Air and earth — they dream it, you build it.","strength":2}],"dealbreakers":"Jealousy. Astrology skeptics. Bad playlists."}'::jsonb, 4, true, 'Builds synths. Will explain them if you ask once.', 3, false),
  ('s26', 'Sol', 26, 'pisces', 'cancer', 'scorpio', 'img/people/p7.jpg', false, null, '{"initial":"Sol","serial":"№ 036","pull":"Strong pull","reading":[{"kind":"pull","text":"Neptune softens your edges. Easy silence.","strength":3},{"kind":"push","text":"They feel it all at once; you take a week.","strength":1},{"kind":"align","text":"Water feeds earth — tender, slow, real.","strength":3}],"dealbreakers":"Coldness. Rushing. Never asking how my day was."}'::jsonb, null, false, 'Ceramicist. Bad at texting, great at long walks.', 4, false),
  ('k28', 'Kai', 28, 'capricorn', 'taurus', 'virgo', 'img/people/p2.jpg', false, null, '{"initial":"Kai","serial":"№ 038","pull":"Steady pull","reading":[{"kind":"pull","text":"Saturn on your Sun — you both mean what you say.","strength":2},{"kind":"push","text":"Two calendars, zero spontaneity.","strength":2},{"kind":"align","text":"Earth on earth — build something that lasts.","strength":3}],"dealbreakers":"Being late. Not having goals. Chaos for fun."}'::jsonb, null, false, 'Architect. Plans the whole trip, forgets the charger.', 5, false),
  ('l26', 'Lena', 26, 'gemini', 'aquarius', 'leo', 'img/people/p1.jpg', false, null, '{"initial":"Lena","serial":"№ 041","pull":"Wild card","reading":[{"kind":"pull","text":"Mercury meets your Venus — she flirts in full sentences.","strength":3},{"kind":"push","text":"She wants three plans; you want the one you made.","strength":2},{"kind":"align","text":"Air and earth — she keeps it light, you keep it real.","strength":2}],"dealbreakers":"Bad texters. Nowhere to dance. People who never ask a question back."}'::jsonb, null, false, 'Podcast producer. Three new hobbies a month, one keeper.', 6, false),
  ('a29', 'Amara', 29, 'sagittarius', 'leo', 'aries', 'img/people/p8.jpg', false, null, '{"initial":"Amara","serial":"№ 044","pull":"Strong pull","reading":[{"kind":"pull","text":"Mars on your Moon — she makes the first move, every time.","strength":3},{"kind":"push","text":"She moves fast; you move once and for good.","strength":3},{"kind":"align","text":"Fire warms earth — she starts it, you make it last.","strength":2}],"dealbreakers":"Indecision. Cancelled plans. Anyone who can’t laugh at themselves."}'::jsonb, null, false, 'Flight attendant. Home for the weekend, maybe yours.', 7, false),
  ('t30', 'Theo', 30, 'cancer', 'virgo', 'virgo', 'img/people/p11.jpg', false, null, '{"initial":"Theo","serial":"№ 047","pull":"Steady pull","reading":[{"kind":"pull","text":"Moon on your Venus — he remembers how you take your coffee.","strength":3},{"kind":"push","text":"He needs reassurance; you assume it’s obvious.","strength":2},{"kind":"align","text":"Water softens earth — home is where you both land.","strength":2}],"dealbreakers":"Coldness. Flaky plans. People who never call their mum."}'::jsonb, null, false, 'Teacher. Brings you soup when you’re sick, unasked.', 8, false),
  ('n27', 'Noor', 27, 'libra', 'gemini', 'gemini', 'img/people/p5.jpg', false, 77, '{"initial":"Noor","serial":"№ 049","pull":"Slow burn","reading":[{"kind":"pull","text":"Venus rules you both — easy taste, easy laughs.","strength":3},{"kind":"push","text":"She weighs every option; you picked an hour ago.","strength":2},{"kind":"align","text":"Air lifts earth — she brings the ideas, you bring the plan.","strength":2}],"dealbreakers":"Rudeness to waiters. One-word answers. Bad shoes."}'::jsonb, null, false, 'Interior designer. Will judge your couch, kindly.', 9, false),
  ('j28', 'Jae', 28, 'sagittarius', 'aries', 'aries', 'img/people/p4.jpg', false, null, '{"initial":"Jae","serial":"№ 052","pull":"Wild card","reading":[{"kind":"pull","text":"Jupiter on your Sun — he makes the night bigger.","strength":3},{"kind":"push","text":"He wants a passport; you want a porch.","strength":2},{"kind":"align","text":"Fire and earth — he finds the road, you find the way home.","strength":2}],"dealbreakers":"Small talk. Closed minds. Anyone who hates travel."}'::jsonb, null, false, 'Photographer. Passport is always in the bag.', 10, false),
  ('b25', 'Bianca', 25, 'taurus', 'pisces', 'pisces', 'img/people/p10.jpg', false, null, '{"initial":"Bianca","serial":"№ 055","pull":"Strong pull","reading":[{"kind":"pull","text":"Same sun — you already know each other’s silences.","strength":3},{"kind":"push","text":"Two bulls, one remote. Nobody gives it up.","strength":2},{"kind":"align","text":"Earth on earth — slow, sure, and very well fed.","strength":2}],"dealbreakers":"Rushing. Cheap wine. Being late to dinner."}'::jsonb, null, false, 'Pastry chef. Up at 4am, asleep by 9, worth it.', 11, false),
  ('i24', 'Ivy', 24, 'pisces', 'taurus', 'taurus', 'img/people/p12.jpg', false, 203, '{"initial":"Ivy","serial":"№ 058","pull":"Steady pull","reading":[{"kind":"pull","text":"Her Moon is your sun — she feels you before you speak.","strength":3},{"kind":"push","text":"She drifts; you anchor. Sometimes too hard.","strength":2},{"kind":"align","text":"Water feeds earth — tender, slow, real.","strength":2}],"dealbreakers":"Cynics. Shouting. Anyone who laughs at horoscopes."}'::jsonb, null, false, 'Music therapist. Sings in the car, badly, on purpose.', 12, false),
  ('d31', 'Dev', 31, 'leo', 'libra', 'libra', 'img/people/p6.jpg', false, null, '{"initial":"Dev","serial":"№ 061","pull":"Wild card","reading":[{"kind":"pull","text":"Sun square Sun — instant heat, instant opinions.","strength":3},{"kind":"push","text":"He wants the spotlight; you want the good seat.","strength":2},{"kind":"align","text":"Fire warms earth — he lights it, you keep it going.","strength":2}],"dealbreakers":"Being ignored. Grey outfits. Leaving early."}'::jsonb, null, false, 'Stand-up on Thursdays. Fintech the rest of the week.', 13, false),
  ('r29b', 'Rosa', 29, 'gemini', 'cancer', 'cancer', 'img/people/p7.jpg', false, null, '{"initial":"Rosa","serial":"№ 064","pull":"Slow burn","reading":[{"kind":"pull","text":"Mercury on your Moon — she talks you out of your shell.","strength":3},{"kind":"push","text":"She changes plans; you change nothing.","strength":2},{"kind":"align","text":"Air and earth — she keeps it moving, you keep it real.","strength":2}],"dealbreakers":"Boredom. Texting “k”. Anyone who won’t try the new place."}'::jsonb, null, false, 'Journalist. Asks one question too many. Sorry.', 14, false),
  ('e30', 'Elio', 30, 'aquarius', 'gemini', 'gemini', 'img/people/p2.jpg', false, null, '{"initial":"Elio","serial":"№ 071","pull":"Wild card","reading":[{"kind":"pull","text":"Uranus crosses your Venus — nothing about him is predictable.","strength":3},{"kind":"push","text":"He lives online; you live in the room.","strength":2},{"kind":"align","text":"Air and earth — he brings the new, you keep what’s good.","strength":2}],"dealbreakers":"Routine for its own sake. Phones at dinner (his own rule, he breaks it)."}'::jsonb, null, false, 'Game designer. Thinks in levels, texts in memes.', null, true),
